/**
 * Sistema de Memória para Código Gerado
 * O bot aprende e memoriza todo código gerado com Ollama
 */

const memory = require('./memoryManager');

const CODE_MEMORY_PREFIX = 'CODE::';
const CODE_METADATA_PREFIX = 'CODE_META::';

/**
 * Salva um código gerado na memória do bot
 */
function rememberGeneratedCode(db, userId, codeGenState, generatedCode) {
  const { type, description, answers } = codeGenState;
  
  // Chave única para este código
  const codeKey = `${CODE_MEMORY_PREFIX}${type}-${Date.now()}`;
  
  // Criar item de conhecimento
  const codeItem = {
    id: codeKey,
    query: `${type}: ${description}`, // Para busca futura
    content: generatedCode,
    tags: [type, ...Object.keys(answers)],
    metadata: {
      type,
      description,
      context: answers,
      generatedAt: Date.now(),
      userId,
      model: 'ollama-mistral'
    },
    created_at: Date.now()
  };
  
  // Adicionar à base de conhecimento
  memory.addKnowledge(codeItem);
  
  // Guardar metadados extras para busca eficiente
  const metadata = {
    id: codeKey,
    type,
    description,
    context: answers,
    generatedAt: Date.now(),
    userId
  };
  
  memory.addKnowledge({
    id: CODE_METADATA_PREFIX + codeKey,
    query: `metadata_${codeKey}`,
    content: JSON.stringify(metadata),
    created_at: Date.now()
  });
  
  return codeKey;
}

/**
 * Busca códigos anteriores similares
 */
function findSimilarCode(description, type = null) {
  // Buscar por descrição
  const results = memory.findKnowledgeByKeyword ? 
    memory.findKnowledgeByKeyword(description, 10) : [];
  
  // Filtrar por tipo se especificado
  if (type) {
    return results.filter(r => 
      r.id && r.id.startsWith(CODE_MEMORY_PREFIX) &&
      (r.metadata && r.metadata.type === type || 
       r.query && r.query.startsWith(`${type}:`))
    );
  }
  
  // Retornar apenas códigos gerados
  return results.filter(r => r.id && r.id.startsWith(CODE_MEMORY_PREFIX));
}

/**
 * Busca código por tipo
 */
function findCodeByType(type) {
  // Buscar palavras-chave relacionadas ao tipo
  const keywords = {
    'game': ['game', 'jogo', 'interactive'],
    'web': ['web', 'site', 'html', 'react', 'vue'],
    'api': ['api', 'backend', 'server', 'rest'],
    'script': ['script', 'automation', 'tool'],
    'component': ['component', 'module', 'function']
  };
  
  const searchTerms = keywords[type] || [type];
  let allResults = [];
  
  for (const term of searchTerms) {
    const results = memory.findKnowledgeByKeyword ? 
      memory.findKnowledgeByKeyword(term, 20) : [];
    allResults = allResults.concat(results);
  }
  
  // Remover duplicatas
  const seen = new Set();
  const unique = allResults.filter(r => {
    if (seen.has(r.id)) return false;
    seen.add(r.id);
    return true;
  });
  
  return unique.filter(r => r.id && r.id.startsWith(CODE_MEMORY_PREFIX));
}

/**
 * Gera um resumo do código memorizado
 */
function getCodeSummary(codeItem) {
  if (!codeItem) return null;
  
  const lines = String(codeItem.content || '').split('\n');
  const summary = {
    description: codeItem.query,
    language: detectLanguage(codeItem.content),
    lines: lines.length,
    preview: lines.slice(0, 5).join('\n') + (lines.length > 5 ? '\n...' : '')
  };
  
  return summary;
}

/**
 * Detecta linguagem do código
 */
function detectLanguage(code) {
  const codeStr = String(code || '').toLowerCase();
  
  if (codeStr.includes('```python') || codeStr.match(/^from |^import |def |import pygame/m)) return 'Python';
  if (codeStr.includes('```javascript') || codeStr.includes('```js') || codeStr.match(/const |let |function |console.log/m)) return 'JavaScript';
  if (codeStr.includes('```html') || codeStr.includes('```html') || codeStr.match(/<html|<div|<body/)) return 'HTML/CSS/JS';
  if (codeStr.match(/class.*:|def /)) return 'Python';
  if (codeStr.match(/function |const.*=>|let /)) return 'JavaScript';
  if (codeStr.match(/public class |private |protected /)) return 'Java';
  if (codeStr.match(/async def|import asyncio/)) return 'Python (Async)';
  
  return 'Unknown';
}

/**
 * Retorna estatísticas de aprendizado
 */
function getLearningStats(db) {
  // Buscar todos os códigos memorizados
  const knowledge = memory.findKnowledgeByKeyword ? 
    memory.findKnowledgeByKeyword('', 500) : [];
  
  const codes = knowledge.filter(k => k.id && k.id.startsWith(CODE_MEMORY_PREFIX));
  
  // Agrupar por tipo
  const byType = {};
  const languages = {};
  
  for (const code of codes) {
    const type = code.query?.split(':')[0] || 'unknown';
    const lang = detectLanguage(code.content);
    
    byType[type] = (byType[type] || 0) + 1;
    languages[lang] = (languages[lang] || 0) + 1;
  }
  
  return {
    totalCodes: codes.length,
    byType,
    byLanguage: languages,
    createdAt: Date.now()
  };
}

/**
 * Cria uma resposta inteligente baseada em memória
 */
function buildMemoryResponse(type, description, context) {
  const similar = findSimilarCode(description, type);
  
  if (similar.length === 0) {
    return {
      hasMemory: false,
      message: `Vou gerar um novo código ${type} para: ${description}`
    };
  }
  
  // Encontrou algo similar na memória!
  const best = similar[0];
  const summary = getCodeSummary(best);
  
  return {
    hasMemory: true,
    message: `🧠 Lembrei! Tenho um ${type} similar na minha memória!\n\n📝 ${summary.description}\n💾 ${summary.language} (${summary.lines} linhas)`,
    suggestion: `Quer usar o código anterior ou gerar um novo?`,
    existingCode: best,
    existingCodeId: best.id
  };
}

/**
 * Exporta estatísticas em texto formatado
 */
function formatStats(stats) {
  let text = `
📊 ESTATÍSTICAS DE APRENDIZADO DO BOT

Total de Códigos Memorizados: ${stats.totalCodes}

Por Tipo:
${Object.entries(stats.byType).map(([type, count]) => `  • ${type}: ${count}`).join('\n')}

Por Linguagem:
${Object.entries(stats.byLanguage).map(([lang, count]) => `  • ${lang}: ${count}`).join('\n')}

O seu bot aprendeu muito! 🤖
`;
  return text;
}

module.exports = {
  rememberGeneratedCode,
  findSimilarCode,
  findCodeByType,
  getCodeSummary,
  detectLanguage,
  getLearningStats,
  buildMemoryResponse,
  formatStats
};

/**
 * Analisador de Código Inteligente
 * Analisa, resume e explica qualquer código usando Ollama
 */

const ollama = require('./ollamaIntegration');

/**
 * Detecta se mensagem contém código
 */
function detectCode(message) {
  const text = String(message || '');
  
  // Detecta bloco de código com ```
  const codeBlockMatch = text.match(/```(\w+)?\s*\n([\s\S]*?)```/);
  if (codeBlockMatch) {
    return {
      found: true,
      language: codeBlockMatch[1] || 'unknown',
      code: codeBlockMatch[2].trim(),
      type: 'block'
    };
  }
  
  // Detecta código inline (linhas com indentação ou estrutura de código)
  const lines = text.split('\n');
  const codeLines = lines.filter(l => 
    /^\s{2,}|^(function|def|class|const|let|var|import|from|async|await|return|if|for|while|try|catch)/.test(l)
  );
  
  if (codeLines.length >= 3) {
    return {
      found: true,
      language: 'unknown',
      code: codeLines.join('\n'),
      type: 'inline'
    };
  }
  
  return { found: false };
}

/**
 * Gera prompt para análise de código
 */
function buildAnalysisPrompt(language, code, analysisType = 'summary') {
  const prompts = {
    summary: `
Analise este código ${language} e faça um RESUMO BREVE:

\`\`\`${language}
${code}
\`\`\`

Responda em máximo 3 parágrafos:
1. O que o código faz? (1 parágrafo)
2. Qual é a funcionalidade principal? (1 parágrafo)
3. Entrada, saída e dependências? (1 parágrafo)

Seja direto e objetivo.
`,
    detailed: `
Analise este código ${language} de forma DETALHADA:

\`\`\`${language}
${code}
\`\`\`

Explique:
1. Propósito geral do código
2. Funções/métodos principais
3. Fluxo de execução
4. Entradas e saídas esperadas
5. Possíveis problemas ou melhorias
`,
    learning: `
Você é um professor de programação. Explique este código ${language} para um iniciante:

\`\`\`${language}
${code}
\`\`\`

Explique:
1. O que cada parte faz?
2. Por que foi escrito assim?
3. Conceitos importantes?
4. Como usar este código?
`,
    optimization: `
Você é um especialista em otimização. Analise este código ${language}:

\`\`\`${language}
${code}
\`\`\`

Forneça:
1. Problemas de performance
2. Melhorias possíveis
3. Complexidade de tempo e espaço
4. Sugestões de refatoração
`,
    security: `
Você é um especialista em segurança. Analise este código ${language}:

\`\`\`${language}
${code}
\`\`\`

Identifique:
1. Vulnerabilidades de segurança
2. Inputs validados?
3. Tratamento de erros
4. Melhorias recomendadas
`
  };
  
  return prompts[analysisType] || prompts.summary;
}

/**
 * Detecta a linguagem do código
 */
function detectLanguage(code) {
  const codeStr = String(code || '').toLowerCase();
  
  if (codeStr.match(/^import |^from |def |class |\.py:|python/m)) return 'Python';
  if (codeStr.match(/const |let |function |=>|\.js:|async|await/m)) return 'JavaScript';
  if (codeStr.match(/public class |private |protected |import java/m)) return 'Java';
  if (codeStr.match(/function|procedure|begin|end;|pascal/m)) return 'Pascal';
  if (codeStr.match(/<\?php|=>|\$[a-zA-Z_]/m)) return 'PHP';
  if (codeStr.match(/#include|int main|cout|cin|c\+\+/m)) return 'C++';
  if (codeStr.match(/#include|int main|printf|scanf/m)) return 'C';
  if (codeStr.match(/public static void|class |interface /m)) return 'Java';
  if (codeStr.match(/def |class |import |python/m)) return 'Python';
  if (codeStr.match(/<html|<body|<div|<!DOCTYPE/m)) return 'HTML/CSS';
  if (codeStr.match(/\.sql:|SELECT|INSERT|UPDATE|DELETE|FROM/m)) return 'SQL';
  if (codeStr.match(/go run|package main|func /m)) return 'Go';
  if (codeStr.match(/fn |let |mut |rust/m)) return 'Rust';
  
  return 'unknown';
}

/**
 * Analisa código com Ollama
 */
async function analyzeCode(code, analysisType = 'summary') {
  try {
    const language = detectLanguage(code);
    const prompt = buildAnalysisPrompt(language, code, analysisType);
    
    const result = await ollama.generateCodeWithFallback(prompt);
    
    if (result.success) {
      return {
        success: true,
        language: language,
        analysisType: analysisType,
        analysis: result.code,
        codePreview: code.substring(0, 200) + (code.length > 200 ? '...' : '')
      };
    } else {
      return {
        success: false,
        error: result.error
      };
    }
  } catch (error) {
    return {
      success: false,
      error: error.message
    };
  }
}

/**
 * Formata análise para exibição
 */
function formatAnalysis(analysisResult) {
  if (!analysisResult.success) {
    return `❌ Erro ao analisar: ${analysisResult.error}`;
  }
  
  const typeEmoji = {
    summary: '📝',
    detailed: '📖',
    learning: '🎓',
    optimization: '⚡',
    security: '🔒'
  };
  
  const emoji = typeEmoji[analysisResult.analysisType] || '📊';
  
  return `
${emoji} ANÁLISE DE CÓDIGO (${analysisResult.language})

${analysisResult.analysis}

---
📄 Código analisado: ${analysisResult.codePreview}
`;
}

/**
 * Gera sugestões baseadas em análise
 */
function generateSuggestions(codeSnippet) {
  const suggestions = [];
  
  const code = String(codeSnippet || '').toLowerCase();
  
  // Detectar problemas comuns
  if (code.includes('eval(')) suggestions.push('⚠️ Evite usar eval() - risco de segurança');
  if (code.match(/while\s*\(\s*true\s*\)/)) suggestions.push('⚠️ Loop infinito detectado');
  if (code.includes('console.log') && code.includes('production')) suggestions.push('⚠️ Remove console.log em produção');
  if (!code.includes('try') && code.includes('error')) suggestions.push('⚠️ Considere adicionar try-catch');
  if (code.includes('TODO') || code.includes('FIXME')) suggestions.push('⚠️ Código com TODOs pendentes');
  if (code.match(/\s{20,}/)) suggestions.push('💡 Reduza indentação/complexidade');
  if (code.length > 1000) suggestions.push('💡 Código muito longo - considere dividir em funções');
  
  return suggestions;
}

/**
 * Detecta intenção natural do usuário (sem precisar de /)
 * Retorna: { detected: true/false, intention: 'analyze'|'correct'|'create'|'explain'|'optimize'|'security'|'refactor'|'improve' }
 */
function detectIntention(message) {
  const text = (message || '').toLowerCase();
  
  // Padrões de intenção
  const patterns = {
    analyze: /analisa|analise|analyze|analisa este código|vê este código|examina|observe este código/i,
    correct: /corrija|corrige|corrijo|fix|conserta|repara|corrige este código|fix this|arruma/i,
    create: /cria|crie|create|monte|montar|faz um|faz|faça um|desenvolve|desenvolva|implemente/i,
    explain: /explica|explique|explain|me ensina|ensina|me explica|como funciona/i,
    optimize: /otimiza|otimize|improve|melhora|melhore|deixa mais rapido|fica mais rapido/i,
    security: /segurança|segurança|security|vulnerabil|vulnerabilidades|unsafe|perigo/i,
    refactor: /refatora|refatore|refactor|reorganiza|reorganize|limpa este código|cleanup/i,
    improve: /melhora|melhore|aproveita|aproveite|enhancement|enhancement/i
  };
  
  for (const [intention, pattern] of Object.entries(patterns)) {
    if (pattern.test(text)) {
      return {
        detected: true,
        intention,
        confidence: 'high'
      };
    }
  }
  
  return { detected: false };
}

/**
 * Mapeia intenção para tipo de análise
 */
function mapIntentionToAnalysisType(intention) {
  const mapping = {
    analyze: 'summary',
    correct: 'optimization',  // Correção é tipo otimização
    explain: 'learning',
    optimize: 'optimization',
    security: 'security',
    refactor: 'optimization',
    improve: 'optimization',
    create: 'create' // Não é análise, é criação
  };
  
  return mapping[intention] || 'summary';
}

module.exports = {
  detectCode,
  analyzeCode,
  detectLanguage,
  formatAnalysis,
  generateSuggestions,
  buildAnalysisPrompt,
  detectIntention,
  mapIntentionToAnalysisType
};

Estruturas de dados essenciais: arrays, objetos (hashmaps), conjuntos (Set) e mapas (Map). Arrays armazenam listas ordenadas; objetos armazenam pares chave/valor. Exemplo de uso:

const arr = [1,2,3];
const obj = { nome: 'Zher', idade: 30 };
arr.forEach(x => console.log(x));

